using System.Globalization;
using System.Text.Json.Nodes;
namespace MyProjectManagement;
public static class WeeklySpreadsheetImports {
 public static readonly string[] Columns=["Visit Reference","Activity Date","Project Code","Company","Module","Activity Code","Consultant","Start Time","End Time","Work Mode","Hours Classification","Notes","Existing Task ID"];
 static bool Same(string a,string b)=>string.Equals(a,b,StringComparison.OrdinalIgnoreCase);
 static int Minute(string value)=>TimeOnly.TryParseExact(value,"HH:mm",out var t)?t.Hour*60+t.Minute:-1;
 static bool MeetingOverlap(JsonObject m,DateOnly date,int start,int end){if(!DateOnly.TryParseExact(J.S(m,"date"),"yyyy-MM-dd",out var d))return false;int minute=Minute(J.S(m,"time"));if(minute<0)return false;var other=d.ToDateTime(TimeOnly.MinValue).AddMinutes(minute);var from=date.ToDateTime(TimeOnly.MinValue).AddMinutes(start);var to=date.ToDateTime(TimeOnly.MinValue).AddMinutes(end);return other<to&&other.AddMinutes((double)J.N(m,"duration"))>from;}
 static string Signature(JsonObject p)=>string.Join("|",new[]{"project","companyId","module","activityId","date","start","end","mode","charge","taskId"}.Select(k=>J.S(p,k).ToUpperInvariant()));
 public static JsonObject Validate(Snapshot state,Policy policy,JsonObject input){J.Require(policy.Active&&policy.Flag("manageWeeklyPlans")&&policy.Flag("assignTasks"),"Weekly planning and task allocation permissions required");var week=J.Day(J.S(input,"weekStart"));J.Require(week.DayOfWeek==DayOfWeek.Monday,"Select a valid Monday-start week",400);J.Require(input["headers"] is JsonArray&&input["rows"] is JsonArray,"Headers and rows required",400);var headers=input["headers"]!.AsArray().Select(x=>SpreadsheetImports.Key(x?.ToString()??"")).ToArray();J.Require(headers.Length is >0 and <=30&&headers.Distinct().Count()==headers.Length&&headers.All(h=>Columns.Any(c=>SpreadsheetImports.Key(c)==h)),"Use the weekly visit template headings",400);foreach(var c in Columns.Where(c=>!new[]{"Work Mode","Hours Classification","Notes","Existing Task ID"}.Contains(c)))J.Require(headers.Contains(SpreadsheetImports.Key(c)),"Missing column: "+c,400);var source=input["rows"]!.AsArray();J.Require(source.Count is >0 and <=500,"Import 1–500 weekly visit rows",400);var translated=new JsonArray();var original=new List<Dictionary<string,string>>();var sourceNumbers=new JsonArray();int index=0;foreach(var value in source){J.Require(value is JsonArray&&value.AsArray().Count<=30,"Invalid weekly row",400);var cells=value!.AsArray();J.Require(cells.All(c=>c is null||c is JsonValue)&&cells.All(c=>(c?.ToString().Length??0)<=6000)&&cells.Skip(headers.Length).All(c=>string.IsNullOrWhiteSpace(c?.ToString())),"Invalid or oversized weekly cells",400);int row=index+2;if(input["rowNumbers"] is JsonArray numbers){J.Require(numbers.Count==source.Count&&numbers[index] is JsonValue n&&n.TryGetValue<int>(out row)&&row>=2&&row<=1048576,"Invalid source row number",400);}index++;if(cells.All(c=>string.IsNullOrWhiteSpace(c?.ToString())))continue;string Get(string name){int i=Array.IndexOf(headers,SpreadsheetImports.Key(name));return i>=0&&i<cells.Count?cells[i]?.ToString().Trim()??"":"";}var raw=Columns.ToDictionary(c=>c,Get);original.Add(raw);sourceNumbers.Add(row);var date=Get("Activity Date");var start=Minute(Get("Start Time"));var end=Minute(Get("End Time"));var hours=start>=0&&end>start?(end-start)/60m:1;translated.Add(new JsonArray(Get("Visit Reference"),Get("Project Code"),Get("Company"),Get("Module"),Get("Activity Code"),Get("Consultant"),date,date,hours.ToString(CultureInfo.InvariantCulture),"Medium",Get("Notes")));}
 var planInput=new JsonObject{["headers"]=new JsonArray(SpreadsheetImports.PlanColumns.Select(c=>(JsonNode?)JsonValue.Create(c)).ToArray()),["rows"]=translated,["rowNumbers"]=sourceNumbers};var lookup=SpreadsheetImports.Validate(state,policy,"project-plan",planInput,true);var items=new JsonArray();var existing=state.Records.Where(k=>k.Key.StartsWith("task:")).SelectMany(k=>J.A(k.Value,"allocations").Select(a=>(task:k.Value,allocation:a))).ToList();
 int irow=0;foreach(var item in J.A(lookup,"items")){var t=item["payload"]!.AsObject();var raw=original[irow++];var errors=new JsonArray(item["errors"]!.AsArray().Select(x=>(JsonNode?)JsonValue.Create(x!.ToString().Replace("Plan Reference","Visit Reference"))).ToArray());var warnings=new JsonArray();if(raw["Activity Date"]=="")warnings.Add("Activity Date defaulted to today");if(item["warnings"]!.AsArray().Any(n=>n?.ToString().StartsWith("Single project")==true))warnings.Add("Single project company selected automatically");var date=J.S(t,"plannedStart");bool validDate=DateOnly.TryParseExact(date,"yyyy-MM-dd",out var day);if(!validDate||day<week||day>week.AddDays(6))errors.Add("Activity Date must be within selected week "+week.ToString("yyyy-MM-dd")+" to "+week.AddDays(6).ToString("yyyy-MM-dd"));var start=Minute(raw["Start Time"]);var end=Minute(raw["End Time"]);if(start<0||end<=start)errors.Add("Use HH:mm start/end times; finish must be later on the same day");var mode=new[]{"Onsite","Offsite"}.FirstOrDefault(s=>Same(s,raw["Work Mode"]==""?"Onsite":raw["Work Mode"]));var charge=new[]{"Client","Internal"}.FirstOrDefault(s=>Same(s,raw["Hours Classification"]==""?"Client":raw["Hours Classification"]));if(mode is null)errors.Add("Work Mode must be Onsite or Offsite");if(charge is null)errors.Add("Hours Classification must be Client or Internal");var taskId=raw["Existing Task ID"];if(taskId!=""){var task=state.Records.GetValueOrDefault("task:"+taskId);if(task is null||J.S(task,"status")=="Completed"||new[]{"project","companyId","module","activityId","typeId"}.Any(k=>!Same(J.S(task,k),J.S(t,k)))||!(J.S(task,"assignee")==J.S(t,"assignee")||J.A(task,"allocations").Any(a=>J.S(a,"assignee")==J.S(t,"assignee"))))errors.Add("Existing Task ID must match project/company/module/activity/type and consultant participation");}
 var p=new JsonObject{["reference"]=J.S(t,"planImportReference"),["project"]=J.S(t,"project"),["companyId"]=J.S(t,"companyId"),["module"]=J.S(t,"module"),["activityId"]=J.S(t,"activityId"),["assignee"]=J.S(t,"assignee"),["date"]=date,["start"]=raw["Start Time"],["end"]=raw["End Time"],["mode"]=mode??raw["Work Mode"],["charge"]=charge??raw["Hours Classification"],["notes"]=raw["Notes"],["taskId"]=taskId,["task"]=t.DeepClone()};
 if(existing.Any(e=>J.S(e.task,"project")==J.S(p,"project")&&Same(J.S(e.allocation,"weeklyImportReference"),J.S(p,"reference"))))errors.Add("Visit Reference was already imported for this project; existing visits are not overwritten");
 if(start>=0&&end>start&&validDate){if(existing.Any(e=>J.S(e.allocation,"assignee")==J.S(p,"assignee")&&J.S(e.allocation,"date")==date&&e.allocation["plannedHours"] is null&&Minute(J.S(e.allocation,"plannedStartTime"))<end&&Minute(J.S(e.allocation,"plannedEndTime"))>start))errors.Add("Consultant already has an overlapping daily allocation");if(state.Records.Where(k=>k.Key.StartsWith("meeting:")).Select(k=>k.Value).Any(m=>!J.B(m,"hoursOnly")&&J.S(m,"calendarSource")!="daily-allocation"&&J.S(m,"assignee")==J.S(p,"assignee")&&MeetingOverlap(m,day,start,end)))errors.Add("Consultant already has an overlapping meeting");}
 items.Add(new JsonObject{["row"]=item["row"]!.DeepClone(),["display"]=new JsonArray(J.S(p,"reference"),date,raw["Project Code"],item["display"]![2]!.ToString(),J.S(p,"module"),raw["Activity Code"],item["display"]![5]!.ToString(),raw["Start Time"],raw["End Time"],J.S(p,"mode"),J.S(p,"charge"),raw["Notes"],taskId),["payload"]=p,["errors"]=errors.DeepClone(),["warnings"]=warnings});}
 var list=items.OfType<JsonObject>().ToList();foreach(var item in list){var p=item["payload"]!.AsObject();var errors=item["errors"]!.AsArray();var group=list.Where(x=>J.S(x["payload"],"project")==J.S(p,"project")&&Same(J.S(x["payload"],"reference"),J.S(p,"reference"))).ToList();if(group.Any(x=>Signature(x["payload"]!.AsObject())!=Signature(p)))errors.Add("Rows sharing a Visit Reference must describe the same visit; use a different reference for another session");if(group.Count(x=>J.S(x["payload"],"assignee")==J.S(p,"assignee"))>1)errors.Add("Duplicate consultant for this Visit Reference");int start=Minute(J.S(p,"start")),end=Minute(J.S(p,"end"));if(start>=0&&end>start&&list.Any(other=>!ReferenceEquals(other,item)&&J.S(other["payload"],"assignee")==J.S(p,"assignee")&&J.S(other["payload"],"date")==J.S(p,"date")&&Minute(J.S(other["payload"],"start"))<end&&Minute(J.S(other["payload"],"end"))>start))errors.Add("Consultant has overlapping rows within this file");}
 return new JsonObject{["kind"]="weekly-site-visits",["revision"]=state.Revision,["weekStart"]=week.ToString("yyyy-MM-dd"),["columns"]=new JsonArray(Columns.Select(c=>(JsonNode?)JsonValue.Create(c)).ToArray()),["items"]=items,["validCount"]=list.Count(x=>x["errors"]!.AsArray().Count==0),["invalidCount"]=list.Count(x=>x["errors"]!.AsArray().Count>0)};
 }
 public static JsonObject Apply(Snapshot state,Policy policy,JsonObject input){var preview=Validate(state,policy,input);J.Require(J.N(preview,"invalidCount")==0,"Weekly import contains errors. Fix and preview again; no rows saved",400);string batch=Guid.NewGuid().ToString();var changed=new Dictionary<string,JsonObject>();var groups=J.A(preview,"items").Select(x=>x["payload"]!.AsObject()).GroupBy(p=>J.S(p,"project")+"|"+J.S(p,"reference").ToUpperInvariant());int count=0;foreach(var group in groups){var first=group.First();string existingId=J.S(first,"taskId");var task=existingId==""?J.Clone(first["task"]!.AsObject()):changed.TryGetValue(existingId,out var current)?current:J.Clone(state.Records["task:"+existingId]);if(existingId==""){task.Remove("planImportReference");task.Remove("planImportedAt");task.Remove("planImportedBy");}var team=group.Count()>1?Guid.NewGuid().ToString():"";foreach(var p in group){var allocation=new JsonObject{["id"]=Guid.NewGuid().ToString(),["assignee"]=J.S(p,"assignee"),["date"]=J.S(p,"date"),["plannedStartTime"]=J.S(p,"start"),["plannedEndTime"]=J.S(p,"end"),["plannedBreakMinutes"]=0,["typeId"]=J.S(task,"typeId"),["workMode"]=J.S(p,"mode"),["chargeType"]=J.S(p,"charge"),["instructions"]=J.S(p,"notes"),["status"]="Planned",["actualStartTime"]="",["actualEndTime"]="",["actualBreakMinutes"]=0,["actualHistory"]=new JsonArray(),["completionRemarks"]="",["billableToClient"]=true,["billingConfirmed"]=false,["weeklyPlanId"]=batch,["weeklyWeek"]=J.S(preview,"weekStart"),["teamGroupId"]=team,["weeklyImportReference"]=J.S(p,"reference"),["weeklyImportedBy"]=policy.Actor,["weeklyImportedAt"]=DateTimeOffset.UtcNow.ToString("O")};(task["allocations"]??=new JsonArray()).AsArray().Add(allocation);count++;}changed[J.S(task,"id")]=task;}
 policy.Apply(new JsonObject{["records"]=new JsonArray(changed.Values.Select(t=>(JsonNode)new JsonObject{["kind"]="task",["id"]=J.S(t,"id"),["payload"]=t}).ToArray())});return new JsonObject{["kind"]="weekly-site-visits",["count"]=count,["weekStart"]=J.S(preview,"weekStart")};}
}
